import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"

        # Retry logic for network errors
        for attempt in range(2):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.status
                    body = response.read().decode('utf-8')

                    if status == 429:
                        # Rate limit: retry up to 3 times with exponential backoff
                        backoff_times = [0.5, 1.0, 2.0]
                        for i in range(3):
                            time.sleep(backoff_times[i])
                            try:
                                req = urllib.request.Request(url)
                                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                                    if resp.status == 429:
                                        if i == 2:
                                            raise RateLimitError("Rate limit exceeded after 3 retries")
                                    else:
                                        return resp.read().decode('utf-8')
                            except urllib.error.HTTPError as e:
                                if e.code == 429:
                                    if i == 2:
                                        raise RateLimitError("Rate limit exceeded after 3 retries")
                                else:
                                    return e.read().decode('utf-8')
                        raise RateLimitError("Rate limit exceeded after 3 retries")

                    elif 500 <= status < 600:
                        # Server error: retry once after 1s
                        time.sleep(1)
                        try:
                            req = urllib.request.Request(url)
                            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                                if 500 <= resp.status < 600:
                                    raise ServerError(f"Server error: {resp.status}")
                                return resp.read().decode('utf-8')
                        except urllib.error.HTTPError as e:
                            if 500 <= e.code < 600:
                                raise ServerError(f"Server error: {e.code}")
                            return e.read().decode('utf-8')

                    elif 400 <= status < 500:
                        # Client error (except 429): raise immediately
                        raise ClientError(f"Client error: {status}")

                    else:
                        return body

            except urllib.error.URLError:
                # Network error: retry once after 1s
                if attempt == 0:
                    time.sleep(1)
                else:
                    raise ConnectionError("Connection failed after retry")

        raise ConnectionError("Connection failed after retry")
